   456  static pgp_armored_msg_t
   457  armor_str_to_data_type(const char *str, size_t len)
   458  {
   459      if (!str) {
   460          return PGP_ARMORED_UNKNOWN;
   461      }
   462      if (!strncmp(str, "BEGIN PGP MESSAGE", len)) {
   463          return PGP_ARMORED_MESSAGE;
   464      }
   465      if (!strncmp(str, "BEGIN PGP PUBLIC KEY BLOCK", len) ||
   466          !strncmp(str, "BEGIN PGP PUBLIC KEY", len)) {
   467          return PGP_ARMORED_PUBLIC_KEY;
   468      }
   469      if (!strncmp(str, "BEGIN PGP SECRET KEY BLOCK", len) ||
   470          !strncmp(str, "BEGIN PGP SECRET KEY", len) ||
   471          !strncmp(str, "BEGIN PGP PRIVATE KEY BLOCK", len) ||
   472          !strncmp(str, "BEGIN PGP PRIVATE KEY", len)) {
   473          return PGP_ARMORED_SECRET_KEY;
   474      }
   475      if (!strncmp(str, "BEGIN PGP SIGNATURE", len)) {
   476          return PGP_ARMORED_SIGNATURE;
   477      }
   478      if (!strncmp(str, "BEGIN PGP SIGNED MESSAGE", len)) {
   479          return PGP_ARMORED_CLEARTEXT;
   480      }
   481      return PGP_ARMORED_UNKNOWN;
   482  }
