   484  pgp_armored_msg_t
   485  rnp_armor_guess_type(pgp_source_t *src)
   486  {
   487      uint8_t ptag;
   488
   489      if (!src_peek_eq(src, &ptag, 1)) {
   490          return PGP_ARMORED_UNKNOWN;
   491      }
   492
   493      switch (get_packet_type(ptag)) {
   494      case PGP_PKT_PK_SESSION_KEY:
   495      case PGP_PKT_SK_SESSION_KEY:
   496      case PGP_PKT_ONE_PASS_SIG:
   497      case PGP_PKT_SE_DATA:
   498      case PGP_PKT_SE_IP_DATA:
   499      case PGP_PKT_COMPRESSED:
   500      case PGP_PKT_LITDATA:
   501          return PGP_ARMORED_MESSAGE;
   502      case PGP_PKT_PUBLIC_KEY:
   503      case PGP_PKT_PUBLIC_SUBKEY:
   504          return PGP_ARMORED_PUBLIC_KEY;
   505      case PGP_PKT_SECRET_KEY:
   506      case PGP_PKT_SECRET_SUBKEY:
   507          return PGP_ARMORED_SECRET_KEY;
   508      case PGP_PKT_SIGNATURE:
   509          return PGP_ARMORED_SIGNATURE;
   510      default:
   511          return PGP_ARMORED_UNKNOWN;
   512      }
   513  }
