   515  pgp_armored_msg_t
   516  rnp_armored_get_type(pgp_source_t *src)
   517  {
   518      char        hdr[128];
   519      const char *armhdr;
   520      size_t      armhdrlen;
   521      size_t      read;
   522
   523      if (!src_peek(src, hdr, sizeof(hdr), &read) || (read < 20)) {
   524          return PGP_ARMORED_UNKNOWN;
   525      }
   526      if (!(armhdr = find_armor_header(hdr, read, &armhdrlen))) {
   527          return PGP_ARMORED_UNKNOWN;
   528      }
   529
   530      return armor_str_to_data_type(armhdr + 5, armhdrlen - 10);
   531  }
