   577  static bool
   578  armor_skip_line(pgp_source_t *src)
   579  {
   580      char header[1024] = {0};
   581      do {
   582          size_t hdrlen = 0;
   583          bool   res = src_peek_line(src, header, sizeof(header), &hdrlen);
   584          if (hdrlen) {
   585              src_skip(src, hdrlen);
   586          }
   587          if (res || (hdrlen < sizeof(header) - 1)) {
   588              return res;
   589          }
   590      } while (1);
   591  }
